  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello रतन जी आपको bridal silk साड़ी की requirement है ना?"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "हाँ।"
    },
    {
      "i": 2,
      "speaker": "bot",
      "text": "आप जिस seller को call कर रहे थे वो available नहीं है और मैं IndiaMART से बोल रही हूं।"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "आपको कितने piece चाहिए?"
    },
    {
      "i": 4,
      "speaker": "caller",
      "text": "One."
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "ठीक है अब work के बारे में बात कर लेते हैं।"
    },
    {
      "i": 6,
      "speaker": "bot",
      "text": "आपको weaving चाहिए या hand work या कुछ और?"
    },
    {
      "i": 7,
      "speaker": "caller",
      "text": "Polythene."
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "Sorry आपकी आवाज़ clear नहीं आई।"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "ज़रा दोबारा बताइए कि आपको work में क्या prefer करेंगे?"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "समझा नहीं।"
    },
    {
      "i": 11,
      "speaker": "bot",
      "text": "ठीक है कोई बात नहीं आपको मैं seller details..."
    },
    {
      "i": 12,
      "speaker": "caller",
      "text": "details WhatsApp पे भेज दूंगी जिनसे आप details और price discuss कर सकते हैं।"
    },
    {
      "i": 13,
      "speaker": "caller",
      "text": "IndiaMART चुनने के लिए धन्यवाद।"
    },
    {
      "i": 14,
      "speaker": "caller",
      "text": "आपका दिन शुभ हो।"
    }
  ]
}
